)


def _prerelease_key(prerelease):
    """Return a comparison key for a pre-release string (or None)."""
    if prerelease is None:
        # A normal release sorts after any pre-release of the same core.
        return (1, ())

    identifiers = []
    for identifier in prerelease.split("."):
        if identifier.isdigit():
            # Numeric identifiers compare numerically and sort before
            # alphanumeric identifiers.
            identifiers.append((0, int(identifier)))
        else:
